val query = """
  {
    __type(name: "User") {
      name
      fields {
        name
        type { name }
      }
    }
  }
"""

val res: IO[Json] = TestMapping.compileAndRun(query)
// data.__type.name == "User", fields == [id, name, birthday]

// Fully disabled: __type/__schema become unknown fields
val res1 = TestMapping.compileAndRun(query, introspectionLevel = Disabled)
// => { "errors": [ { "message": "No field '__type' for type Query" } ] }

// TypenameOnly: __typename still works, __schema/__type rejected
val typenameQuery = """{ users { __typename renamed: __typename name } }"""
val res2 = SmallMapping.compileAndRun(typenameQuery, introspectionLevel = TypenameOnly)
// => data.users[0].__typename == "User"

val query = """
  query ($yup: Boolean, $nope: Boolean) {
    a: field @skip(if: $yup)    { subfieldA }
    b: field @skip(if: $nope)   { subfieldB }
    c: field @include(if: $yup) { subfieldA }
    d: field @include(if: $nope){ subfieldB }
  }
"""
val variables = json"""{ "yup": true, "nope": false }"""

val compiled = SkipIncludeMapping.compiler.compile(query, untypedVars = Some(variables))
// only the 'b' and 'c' selections survive; 'a' and 'd' are dropped (Query.Empty)

